def raiz_cuadrada_entera(n: int) -> int:
    """Raíz cuadrada entera usando búsqueda binaria."""
    if n < 0:
        raise ValueError("n debe ser no negativo")
    izq, der = 0, n
    while izq <= der:
        mid = (izq + der) // 2
        if mid * mid == n:
            return mid
        if mid * mid < n:
            izq = mid + 1
            ultimo = mid
        else:
            der = mid - 1
    return ultimo

print(raiz_cuadrada_entera(8))   # 2
print(raiz_cuadrada_entera(25))  # 5

def busqueda_binaria(arr: list, objetivo) -> int:
    """Retorna el índice del objetivo, o -1 si no existe."""
    izq, der = 0, len(arr) - 1
    while izq <= der:
        mid = (izq + der) // 2
        if arr[mid] == objetivo:
            return mid
        if arr[mid] < objetivo:
            izq = mid + 1
        else:
            der = mid - 1
    return -1

arr = [1, 3, 5, 7, 9, 11, 13]
print(busqueda_binaria(arr, 7))   # 3
print(busqueda_binaria(arr, 4))   # -1

def primer_mayor_o_igual(arr: list, objetivo) -> int:
    """Lower bound: primer índice donde arr[i] >= objetivo."""
    izq, der = 0, len(arr)
    while izq < der:
        mid = (izq + der) // 2
        if arr[mid] < objetivo:
            izq = mid + 1
        else:
            der = mid
    return izq

arr = [1, 2, 4, 4, 5, 8, 10]
print(primer_mayor_o_igual(arr, 4))  # 2 (primer 4)
print(primer_mayor_o_igual(arr, 6))  # 5 (primer >= 6 es 8)

def rotated_search(arr: list, objetivo: int) -> int:
    """Búsqueda binaria en array rotado."""
    izq, der = 0, len(arr) - 1
    while izq <= der:
        mid = (izq + der) // 2
        if arr[mid] == objetivo:
            return mid
        if arr[izq] <= arr[mid]:  # izquierda ordenada
            if arr[izq] <= objetivo < arr[mid]:
                der = mid - 1
            else:
                izq = mid + 1
        else:  # derecha ordenada
            if arr[mid] < objetivo <= arr[der]:
                izq = mid + 1
            else:
                der = mid - 1
    return -1

print(rotated_search([4,5,6,7,0,1,2], 0))  # 4

def encontrar_pico(arr: list) -> int:
    """Encontrar cualquier elemento pico (mayor a sus vecinos)."""
    izq, der = 0, len(arr) - 1
    while izq < der:
        mid = (izq + der) // 2
        if arr[mid] > arr[mid + 1]:
            der = mid
        else:
            izq = mid + 1
    return izq

