public static class BSTExtensions
{
    public static Node DestroySubtree(this Node root, int target)
    {
        if (root == null)
        {
            return null;
        }
        if (target < root.Data)
        {
            root.Left = DestroySubtree(root.Left, target);
        }
        else if (target > root.Data)
        {
            root.Right = DestroySubtree(root.Right, target);
