import Foundation

class MergeSort {
    static func execute() {
        let unsortedArraySample = [10, 3, 1, 7, 0, 2, 8]
        let sortedArray = sort(unsortedArraySample)
        print("Sorted Array: \(sortedArray)")
    }

    static func sort(_ array: [Int]) -> [Int] {
        guard array.count > 1 else {
            return array
        }

        let middleIndex = array.count / 2
        let leftArray = sort(Array(array[0..<middleIndex]))
        let rightArray = sort(Array(array[middleIndex..<array.count]))

        return merge(leftArray, rightArray)
    }

    private static func merge(_ leftArray: [Int], _ rightArray: [Int]) -> [Int] {
        var mergedArray: [Int] = []
        var leftIndex = 0
        var rightIndex = 0

        while leftIndex < leftArray.count && rightIndex < rightArray.count {
            if leftArray[leftIndex] < rightArray[rightIndex] {
                mergedArray.append(leftArray[leftIndex])
                leftIndex += 1
            } else {
                mergedArray.append(rightArray[rightIndex])
                rightIndex += 1
            }
        }

        mergedArray += Array(leftArray[leftIndex...])
        mergedArray += Array(rightArray[rightIndex...])

        return mergedArray
    }
}
