```javascript
class MinMaxHeap {
  constructor() {
    this.heap = [];
  }

  insert(value) {
    this.heap.push(value);
    this.bubbleUp(this.heap.length - 1);
  }

  delete(value) {
    const index = this.heap.indexOf(value);
    if (index !== -1) {
      this.swap(index, this.heap.length - 1);
      this.heap.pop();
      this.bubbleDown(index);
      this.bubbleUp(index);
    }
  }

  get_min() {
    if (this.heap.length === 0) {
      throw new Error("Heap is empty");
    }
    return this.heap[0];
  }

  get_max() {
    if (this.heap.length === 0) {
      throw new Error("Heap is empty");
    }
    if (this.heap.length === 1 || this.heap.length === 2) {
      return this.heap[this.heap.length - 1];
    }
    return this.heap[1];
  }

  bubbleUp(index) {
    if (index === 0) {
      return;
    }
    const parentIndex = Math.floor((index - 1) / 2);
    if (this.isMinLevel(index) && this.heap[index] > this.heap[parentIndex]) {
      this.swap(index, parentIndex);
      this.bubbleUpMax(parentIndex);
    } else if (!this.isMinLevel(index) && this.heap[index] < this.heap[parentIndex]) {
      this.swap(index, parentIndex);
      this.bubbleUpMin(parentIndex);
    }
  }

  bubbleDown(index) {
    if (this.isMinLevel(index)) {
      this.bubbleDownMin(index);
    } else {
      this.bubbleDownMax(index);
    }
  }

  bubbleUpMin(index) {
    if (index <= 2) {
      return;
    }
    const grandparentIndex = Math.floor((index - 3) / 4);
    if (this.heap[index] < this.heap[grandparentIndex]) {
      this.swap(index, grandparentIndex);
      this.bubbleUpMin(grandparentIndex);
    }
  }

  bubbleUpMax(index) {
    if (index === 1) {
      return;
    }
    const grandparentIndex = Math.floor((index - 3) / 4);
    if (this.heap[index] > this.heap[grandparentIndex]) {
      this.swap(index, grandparentIndex);
      this.bubbleUpMax(grandparentIndex);
    }
  }

  bubbleDownMin(index) {
    const leftChildIndex = 2 * index + 1;
    const rightChildIndex = 2 * index + 2;
    let minIndex = index;
    if (leftChildIndex < this.heap.length && this.heap[leftChildIndex] < this.heap[minIndex]) {
      minIndex = leftChildIndex;
    }
    if (rightChildIndex < this.heap.length && this.heap[rightChildIndex] < this.heap[minIndex]) {
      minIndex = rightChildIndex;
    }
    if (minIndex !== index) {
      this.swap(index, minIndex);
      this.bubbleDownMin(minIndex);
    }
  }

  bubbleDownMax(index) {
    const leftChildIndex = 2 * index + 1;
    const rightChildIndex = 2 * index + 2;
    let maxIndex = index;
    if (leftChildIndex < this.heap.length && this.heap[leftChildIndex] > this.heap[maxIndex]) {
      maxIndex = leftChildIndex;
    }
    if (rightChildIndex < this.heap.length && this.heap[rightChildIndex] > this.heap[maxIndex]) {
      maxIndex = rightChildIndex;
    }
    if (maxIndex !== index) {
      this.swap(index, maxIndex);
      this.bubbleDownMax(maxIndex);
    }
  }

  isMinLevel(index) {
    const height = Math.floor(Math.log2(index + 1));
    return height % 2 === 0;
  }

  swap(index1, index2) {
    [this.heap[index1], this.heap[index2]] = [this.heap[index2], this.heap[index1]];
  }
}

