- `contains(&self, value: &T) -> bool`: Checks if a value is present in the BTreeSet.

You need to implement the `BTreeSet` trait for a type `MyBTreeSet` that represents the simplified BTreeSet using a binary search tree. The binary search tree should be defined as follows:
```rust
struct Node<T> {
    value: T,
    left: Option<Box<Node<T>>>,
    right: Option<Box<Node<T>>>,
}
```
The `Node` struct represents a node in the binary search tree. It contains a value of type `T` and optional left and right child nodes.

Your task is to implement the `BTreeSet` trait for the `MyBTreeSet` type, ensuring that the binary search tree maintains the sorted property of the BTreeSet.

### Solution:
```rust
use std::cmp::Ord;

struct Node<T> {
    value: T,
    left: Option<Box<Node<T>>>,
    right: Option<Box<Node<T>>>,
}

impl<T: Ord> Node<T> {
    fn new(value: T) -> Self {
        Node {
            value,
            left: None,
            right: None,
        }
    }

    fn insert(&mut self, value: T) {
        if value <= self.value {
            if let Some(ref mut left) = self.left {
                left.insert(value);
            } else {
                self.left = Some(Box::new(Node::new(value)));
            }
        } else {
            if let Some(ref mut right) = self.right {
                right.insert(value);
            } else {
                self.right = Some(Box::new(Node::new(value)));
            }
        }
    }

    fn contains(&self, value: &T) -> bool {
        if value == &self.value {
            true
        } else if value < &self.value {
            if let Some(ref left) = self.left {
                left.contains(value)
            } else {
                false
            }
        } else {
            if let Some(ref right) = self.right {
                right.contains(value)
            } else {
                false
            }
        }
    }
}

struct MyBTreeSet<T> {
    root: Option<Box<Node<T>>>,
}

impl<T: Ord> MyBTreeSet<T> {
    fn new() -> Self {
        MyBTreeSet { root: None }
    }
}

impl<T: Ord> BTreeSet<T> for MyBTreeSet<T> {
    fn new() -> Self {
        MyBTreeSet { root: None }
    }

    fn insert(&mut self, value: T) {
        if let Some(ref mut root) = self.root {
            root.insert(value);
        } else {
            self.root = Some(Box::new(Node::new(value)));
        }
    }

    fn contains(&self, value: &T) -> bool {
        if let Some(ref root) = self.root {
            root.contains(value)
        } else {
            false
        }
    }
}
```

