        else if (li <= l && ri >= r) return dtr;
        else return min(lc->qrl(li, ri), rc->qrl(li, ri));
    }

    ll qrr(ll li, ll ri) {
        if (li >= r || ri <= l) return LLONG_MIN;
        else if (li <= l && ri >= r) return dtr;
        else return max(lc->qrr(li, ri), rc->qrr(li, ri));
    }

    void clr() {
        if (l == r - 1) {
            dtr = LLONG_MAX;
        } else {
            lc->clr();
            rc->clr();
            dtr = min(lc->dtr, rc->dtr);
        }
    }
};

