#include <vector>
#include <string>
using namespace std;

class GridPaths {
private:
    vector<string> grid;
    int ans;

    void f(int x, int y, int right, int down) {
        if (x == grid.size() - 1 && y == grid[0].size() - 1) {
            ans++;
            return;
        }
        if (right < grid.size() - 1) {
