public boolean update(int value, int newValue) {
    if (value == this.value) {
        this.value = newValue; // update the value
        return true; // update successful
    } else if (value < this.value && left != null) {
        return left.update(value, newValue); // recursively update in the left subtree
    } else if (value > this.value && right != null) {
