### Problem:
You are tasked with implementing a simple parser for a basic arithmetic expression language. The language supports addition, subtraction, multiplication, and division operations, as well as parentheses for grouping. The parser should take an input string representing an arithmetic expression and produce an abstract syntax tree (AST) representing the parsed expression.

You are provided with the following code snippet as a starting point for the parser implementation:

```cpp
ASTNode *expr();

ASTNode *term();

ASTNode *prim();

Lexer &lexer_;
Lexer::Token tok_;
```

Your task is to complete the implementation of the parser by defining the `expr()`, `term()`, and `prim()` functions, and utilizing the `Lexer` class to tokenize the input expression. The `Lexer` class provides a `Token` enum representing different types of tokens in the input expression.

You should define the `ASTNode` class to represent nodes in the abstract syntax tree. Each node should have a type indicating the operation (e.g., addition, multiplication) or the value (for numeric literals), and pointers to its left and right children for binary operations.

Your implementation should handle operator precedence and associativity correctly, and should properly handle parentheses for grouping sub-expressions.

### Solution:
```cpp
#include <iostream>
#include <string>
#include <vector>

enum class Token {
    NUMBER,
    PLUS,
    MINUS,
    MULTIPLY,
    DIVIDE,
    LPAREN,
    RPAREN,
    END
};

class Lexer {
public:
    Lexer(const std::string& input) : input_(input), position_(0) {}

    Token getNextToken() {
        if (position_ == input_.size()) {
            return Token::END;
        }

        char currentChar = input_[position_];
        if (isdigit(currentChar)) {
            return Token::NUMBER;
        } else {
            switch (currentChar) {
                case '+':
                    ++position_;
                    return Token::PLUS;
                case '-':
                    ++position_;
                    return Token::MINUS;
                case '*':
                    ++position_;
                    return Token::MULTIPLY;
                case '/':
                    ++position_;
                    return Token::DIVIDE;
                case '(':
                    ++position_;
                    return Token::LPAREN;
                case ')':
                    ++position_;
                    return Token::RPAREN;
                default:
                    throw std::runtime_error("Invalid character in input");
            }
        }
    }

    int getNumberValue() {
        int value = 0;
        while (position_ < input_.size() && isdigit(input_[position_])) {
            value = value * 10 + (input_[position_] - '0');
            ++position_;
        }
        return value;
    }

private:
    std::string input_;
    size_t position_;
};

class ASTNode {
public:
    enum class Type {
        NUMBER,
        ADDITION,
        SUBTRACTION,
        MULTIPLICATION,
        DIVISION
    };

    Type type;
    int value;
    ASTNode* left;
    ASTNode* right;

    ASTNode(Type type, int value) : type(type), value(value), left(nullptr), right(nullptr) {}

    ASTNode(Type type, ASTNode* left, ASTNode* right) : type(type), value(0), left(left), right(right) {}
};

class Parser {
public:
    Parser(const std::string& input) : lexer_(input), currentToken_(lexer_.getNextToken()) {}

    ASTNode* parse() {
        return expr();
    }

private:
    Lexer lexer_;
    Token currentToken_;

    void eat(Token token) {
        if (currentToken_ == token) {
            currentToken_ = lexer_.getNextToken();
        } else {
            throw std::runtime_error("Unexpected token");
        }
    }

    ASTNode* expr() {
        ASTNode* node = term();

        while (currentToken_ == Token::PLUS || currentToken_ == Token::MINUS) {
            Token op = currentToken_;
            eat(op);
            if (op == Token::PLUS) {
                node = new ASTNode(ASTNode::Type::ADDITION, node, term());
            } else {
                node = new ASTNode(ASTNode::Type::SUBTRACTION, node, term());
            }
        }

        return node;
    }

    ASTNode* term() {
        ASTNode* node = prim();

        while (currentToken_ == Token::MULTIPLY || currentToken_ == Token::DIVIDE) {
            Token op = currentToken_;
            eat(op);
            if (op == Token::MULTIPLY) {
                node = new ASTNode(ASTNode::Type::MULTIPLICATION, node, prim());
            } else {
                node = new ASTNode(ASTNode::Type::DIVISION, node, prim());
            }
        }

        return node;
    }

    ASTNode* prim() {
        Token token = currentToken_;
        if (token == Token::NUMBER) {
            int value = lexer_.getNumberValue();
            eat(Token::NUMBER);
            return new ASTNode(ASTNode::Type::NUMBER, value);
        } else if (token == Token::LPAREN) {
            eat(Token::LPAREN);
            ASTNode* node = expr();
            eat(Token::RPAREN);
            return node;
        } else {
            throw std::runtime_error("Unexpected token");
        }
    }
};

int main() {
    std::string input = "3 + 4 * (2 - 1)";
    Parser parser(input);
    ASTNode* ast = parser.parse();

    // Print the abstract syntax tree
    std::cout << "Abstract Syntax Tree:" << std::endl;
    // Implement a function to print the AST
    printAST(ast);

    return 0;
}
```

In the solution, the `Lexer` class tokenizes the input expression, and the `Parser` class implements the parsing logic using recursive descent parsing. The `ASTNode` class represents nodes in the abstract syntax tree, and the `main` function demonstrates the usage of the parser to parse an input expression and print the abstract syntax tree.

