### Solution:
```c
#include <stdio.h>

int findFirstNegative(int arr[], int n) {
    int low = 0, high = n - 1, firstNegative = -1;

    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] < 0) {
            firstNegative = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    return firstNegative;
}

