class TimeMap:
    def __init__(self):
        self.v = {}  # Dictionary to store values for each key
        self.t = {}  # Dictionary to store timestamps for each key

    def set(self, key, value, timestamp):
        # Append the value and timestamp to the respective lists for the given key
        if key not in self.v:
            self.v[key] = [value]
            self.t[key] = [timestamp]
        else:
            self.v[key].append(value)
            self.t[key].append(timestamp)

    def get(self, key, timestamp):
        if key not in self.t:
            return ""  # Return an empty string if the key is not found
        else:
            # Use binary search to find the appropriate index for the given timestamp
            index = self.bisect(self.t[key], timestamp)
            if index == 0:
                return ""  # Return an empty string if the timestamp is earlier than the first entry
            else:
                return self.v[key][index - 1]  # Return the value associated with the key at the found index

    def bisect(self, arr, target):
        # Binary search implementation to find the appropriate index for the given timestamp
        left, right = 0, len(arr)
        while left < right:
            mid = (left + right) // 2
            if arr[mid] <= target:
                left = mid + 1
            else:
                right = mid
        return left
